"""Read-only evidence validation. Does not alter the original browser report."""
import hashlib,json,struct,sys,urllib.parse
from pathlib import Path
folder=Path(sys.argv[1]);report=json.loads((folder/'report.json').read_text());manifest=json.loads((folder/'tested-dist-sha256.json').read_text())['files'];assets=[];images=[]
for item in report['loadedAssets']:
 name=urllib.parse.unquote(urllib.parse.urlsplit(item['url']).path).lstrip('/');expected=manifest.get(name);assets.append({'file':name,'status':item['status'],'sha256Matches':bool(expected and expected['sha256']==item['sha256'] and expected['bytes']==item['bytes'])})
for cap in report['captures']:
 p=folder/(cap['name']+'.png');raw=p.read_bytes();width,height=struct.unpack('>II',raw[16:24]);must_play=cap['name'].startswith(('driving-','playing-','focus-resumed-','reconnected-'));bounds=cap.get('layout',{}).get('idBounds');images.append({'file':p.name,'sha256':hashlib.sha256(raw).hexdigest(),'sha256Matches':hashlib.sha256(raw).hexdigest()==cap['sha256'],'width':width,'height':height,'viewportMatches':width==cap['viewport']['width'] and height==cap['viewport']['height'],'paused':cap['state']['paused'],'claimedPlayStateCorrect':not must_play or not cap['state']['paused'],'identityWithinPanel':bounds['insidePanel'] if bounds else None,'layout':cap.get('layout',{})})
checks={'browserFinished':report.get('finished') is True,'browserChecksPassed':report.get('passed') is True,'noErrors':not report['errors'],'offline':not report['externalRequests'],'allResponsesMatchFrozenAssets':bool(assets) and all(a['sha256Matches'] and a['status']==200 for a in assets),'allImageHashesAndViewportsMatch':bool(images) and all(i['sha256Matches'] and i['viewportMatches'] for i in images),'claimedGameplayImagesAreNotPaused':all(i['claimedPlayStateCorrect'] for i in images),'recordedIdentityBoundsFit':all(i['identityWithinPanel'] is not False for i in images)}
result={'checks':checks,'passed':all(checks.values()),'runtimeAssets':assets,'images':images,'syntheticBridge':True,'nativeSdkTested':False,'physicalTvTested':False,'physicalPhoneTested':False,'visualReviewStillRequired':True}
(folder/'validation.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'passed':result['passed'],'checks':checks,'responses':len(assets),'images':len(images)},indent=2));sys.exit(0 if result['passed'] else 1)
